export function validateBlockTreatment(name: string, treatment: unknown) { if (!Object.prototype.hasOwnProperty.call(blockTreatmentSchemas,name)) throw Error("Unknown block treatment"); return blockTreatmentSchemas[name as keyof typeof blockTreatmentSchemas].parse(treatment); }

type FieldValidator = { unwrap?: () => FieldValidator; shape?: Record<string, FieldValidator>; element?: FieldValidator; parse: (value: unknown) => unknown };
export function validateBlockField(name: string, path: readonly (string | number)[], value: unknown) {
  if (!Object.prototype.hasOwnProperty.call(blockSchemas, name) || !path.length) throw new Error("Unknown block field");
  let schema = blockSchemas[name as BlockName] as unknown as FieldValidator;
  for (const part of path) {
    let depth = 0;
    while (!schema.shape && !schema.element && schema.unwrap && depth++ < 10) schema = schema.unwrap();
    if (typeof part === "number" && Number.isSafeInteger(part) && part >= 0 && schema.element) schema = schema.element;
    else if (typeof part === "string" && schema.shape && Object.prototype.hasOwnProperty.call(schema.shape, part)) schema = schema.shape[part];
    else throw new Error("Unknown block field path");
  }
  return schema.parse(value);
}
